/* eslint-disable @stencil-community/required-jsdoc */
import { Component, h, Element, Host, VNode, Prop, Watch, State } from '@stencil/core';
import { t } from '@src/shared/i18n';
import { selectMessages } from '@fe-infra/keystone-locales';
import { KsCascaderItem } from '@src/components/ks-menu-item/cascader-item';
import { KsVirtualList } from '@src/components/ks-virtual-list';
import { MenuItemBase, Value } from '../../ks-menu-item/types';
import { renderDynamicChildren, renderItemSlots, renderPassThroughSlots } from '../../ks-menu-item/utils';
import { CascaderDataNode, CascaderSearchNode, SingleValueType, CascaderColumnSelectAllConfig } from '../types';
import { SEARCH_MARK } from '../constants';
import { isLeaf, toPathKey } from '../utils';
import { Consume } from '@src/framework/runtime-context';
import { CascaderContext, CascaderContextValue } from '../context';
import { RenderConfig } from '@src/components/ks-virtual-list/types';

const DEFAULT_HEIGHT = 36;
const DEFAULT_HEIGHT_WITH_DESC = 54;

@Component({
  tag: 'ks-cascader-panel-column',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCascaderPanelColumn extends KsVirtualList<CascaderDataNode | CascaderSearchNode> {
  @Element() override el!: HTMLKsCascaderPanelColumnElement;

  @Prop() options: Readonly<CascaderDataNode[] | CascaderSearchNode[]> = [];

  @Prop() multiple!: boolean;

  /** Current Column opened item key */
  @Prop() activeValue?: Value;

  /** The value path before current column */
  @Prop() prevValuePath: Readonly<Value[]> = [];

  @Prop() onToggleOpen?: (open: boolean) => void;

  @Prop() onSelect?: (valuePath: SingleValueType, leaf: boolean, originalChecked: boolean) => void;

  @Prop() onActive?: (valuePath: SingleValueType) => void;

  @Prop() checkedSet!: Set<Value>;

  @Prop() halfCheckedSet!: Set<Value>;

  @Prop() key2CheckedChildrenCount!: Map<Value, number>;

  @Prop() loadingKeys: Value[] = [];

  @Prop() isSelectable!: (option: CascaderDataNode | CascaderSearchNode) => boolean;

  @Prop() lastColumn!: boolean;

  @Prop() columnSelectAll?: boolean | CascaderColumnSelectAllConfig;

  @Prop() onSelectAll?: (valuePaths: SingleValueType[], checked: boolean) => void;

  protected override prefixCls = 'cascader-panel__column';
  protected override items: Readonly<CascaderDataNode[] | CascaderSearchNode[]> = [];
  protected override renderItem(item: CascaderDataNode | CascaderSearchNode, index: number): VNode {
    const data = item;
    const { value: key } = data;
    const searchOptions = (data as CascaderSearchNode)[SEARCH_MARK];

    const mergedIsLeaf = isLeaf(data);

    // Get real value of option. Search option is different way.
    const fullPath = searchOptions ? searchOptions.map((opt) => opt.value) : [...this.prevValuePath, key];
    const fullPathKey = toPathKey(fullPath);

    const isLoading = this.loadingKeys.includes(fullPathKey);

    const mergedChecked = this.checkedSet.has(fullPathKey);
    const mergedHalfChecked = this.halfCheckedSet.has(fullPathKey);
    const mergedDisabled = data.disabled || isLoading;

    const activeByPath = this.activeValue === fullPathKey || this.activeValue === key;
    // If current option is last column and multiple, it should not be active.
    const isLastColumnAndMultiple = this.lastColumn && this.multiple;
    const mergedActive = activeByPath && !isLastColumnAndMultiple;

    const triggerOpenPath = () => {
      const nextValueCells = [...fullPath];
      // if (mergedIsLeaf) {
      //   nextValueCells.pop();
      // }
      this.onActive?.(nextValueCells);
    };

    const triggerCheck = () => {
      if (this.isSelectable(data) && !mergedDisabled) {
        this.onSelect?.(fullPath, mergedIsLeaf, mergedChecked);
      }
    };

    return (
      <KsCascaderItem
        multiple={this.multiple}
        value={key}
        checked={mergedChecked}
        hideCheckmark={!mergedIsLeaf}
        disabled={mergedDisabled}
        label={typeof data.label === 'string' ? data.label : undefined}
        description={typeof data.description === 'string' ? data.description : undefined}
        helpContent={typeof data.helpContent === 'string' ? data.helpContent : undefined}
        popover={data.popover}
        indeterminate={mergedHalfChecked}
        expandable={!mergedIsLeaf}
        childrenCheckedCount={this.key2CheckedChildrenCount.get(fullPathKey)}
        active={mergedActive}
        lastColumn={this.lastColumn}
        onClick={() => {
          triggerOpenPath();
          if (!this.multiple || mergedIsLeaf) {
            triggerCheck();
          }
        }}
        onCheck={(e: PointerEvent) => {
          e.stopPropagation();
          triggerCheck();
        }}
        // TODO: highlight
        highlight={(item as CascaderSearchNode).highlight || null}
      >
        {renderItemSlots(item, index)}
      </KsCascaderItem>
    );
  }
  protected renderDynamicChildrenForItem(
    item: MenuItemBase<CascaderDataNode | CascaderSearchNode>,
    index: number,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
    renderConfig?: RenderConfig,
  ): unknown[] {
    return renderDynamicChildren(item, index, wrapWithSlot, renderConfig);
  }
  protected override getPassThroughSlots = (item: CascaderDataNode | CascaderSearchNode, index: number): VNode[] =>
    renderPassThroughSlots(item, index);
  protected override DEFAULT_HEIGHT = (item: CascaderDataNode | CascaderSearchNode) => {
    const data = item;
    return data.description ? DEFAULT_HEIGHT_WITH_DESC : DEFAULT_HEIGHT;
  };
  override virtual?:
    | boolean
    | { estimatedItemHeight: number | ((item: CascaderDataNode | CascaderSearchNode) => number) }
    | undefined = true;

  private getSelectableValuePaths() {
    if (!this.multiple || !this.columnSelectAll) {
      return [];
    }

    return (this.options as CascaderDataNode[]).reduce<SingleValueType[]>((valuePaths, option) => {
      const valuePath = [...this.prevValuePath, option.value];
      if (this.isSelectable(option) && !this.loadingKeys.includes(toPathKey(valuePath))) {
        valuePaths.push(valuePath);
      }
      return valuePaths;
    }, []);
  }

  private renderSelectAll() {
    const valuePaths = this.getSelectableValuePaths();
    if (!valuePaths.length) {
      return null;
    }

    const checkedCount = valuePaths.filter((valuePath) => this.checkedSet.has(toPathKey(valuePath))).length;
    const indeterminateCount = valuePaths.filter((valuePath) => this.halfCheckedSet.has(toPathKey(valuePath))).length;
    const checked = checkedCount === valuePaths.length;
    const indeterminate = !checked && (checkedCount > 0 || indeterminateCount > 0);
    const label = typeof this.columnSelectAll === 'object' ? this.columnSelectAll.label : undefined;

    const triggerSelectAll = () => {
      this.onSelectAll?.(valuePaths, !checked);
    };

    return (
      <div class={`${this.prefixCls}__select-all`}>
        <KsCascaderItem
          multiple
          value="__select_all__"
          checked={checked}
          indeterminate={indeterminate}
          label={label ?? t(selectMessages.selectAll)}
          hideCheckmark
          highlight={null}
          active={false}
          lastColumn={false}
          dataAttrs={{ 'data-select-all': 'true' }}
          onClick={triggerSelectAll}
          onCheck={(e: PointerEvent) => {
            e.stopPropagation();
            triggerSelectAll();
          }}
        />
      </div>
    );
  }

  render() {
    const loading = this.loadingKeys.includes(toPathKey(this.prevValuePath));
    return (
      <Host class="KsCascaderPanelColumn">
        <ks-spinner loading={loading}>
          <div class={`${this.prefixCls}__content`}>
            {this.renderSelectAll()}
            {this.renderList()}
          </div>
        </ks-spinner>
      </Host>
    );
  }

  override componentWillLoad(): Promise<void> | void {
    super.componentWillLoad?.();
    this.prepareItemsForRender();
  }

  @Watch('options')
  prepareItemsForRender() {
    this.items = this.options;
  }

  /**
   * @private */
  @Prop() index: number | 'search' = 0;
  @Consume({
    context: CascaderContext,
    subscribe: true,
  })
  @State()
  contextFromCascader?: CascaderContextValue;
  protected override setDynamicRenderDeps = (children: unknown[], getPassThroughSlots: () => VNode[] = () => []) => {
    if (this.index === 'search') {
      this.contextFromCascader?.setDynamicRenderDeps(children, 'search');
      this.contextFromCascader?.updatePassThroughSlotsFnArr([getPassThroughSlots]);
    } else {
      this.contextFromCascader?.setDynamicRenderDeps(children, this.index);
      const newArr = [...(this.contextFromCascader?.getPassThroughSlotsFnArr || [])];
      newArr[this.index] = getPassThroughSlots || (() => []);
      this.contextFromCascader?.updatePassThroughSlotsFnArr(newArr);
    }
  };
  protected override wrapWithSlot = (slotName: string, children: unknown) =>
    this.contextFromCascader?.wrapWithSlot?.(slotName, children);

  ////// DEPS //////
  protected __DEPS__() {
    return [<ks-checkbox />, <ks-tooltip />, <ks-text />];
  }
}
