import { FunctionalComponent, h } from '@stencil/core';
import { CascaderDataNode } from '@src/components/ks-cascader/types';
import { KsMenuItemBase, MenuItemBaseProps } from './item';
import { KsIconChevronRight } from '@fe-infra/keystone-icons-stencil';

const prefix = 'cascader-item';

export interface CascaderItemProps extends MenuItemBaseProps<CascaderDataNode> {
  childrenCheckedCount?: number;
  expandable?: boolean;
  active?: boolean;
  lastColumn?: boolean;
}

export const KsCascaderItem: FunctionalComponent<CascaderItemProps> = (
  { childrenCheckedCount, expandable, active, lastColumn, ...rest },
  children,
) => {
  const { disabled } = rest;
  return (
    <KsMenuItemBase<CascaderItemProps>
      classes={{
        [prefix]: true,
        [`${prefix}--active`]: active || false,
        [`${prefix}--disabled`]: disabled || false,
      }}
      active={active && lastColumn}
      {...rest}
    >
      {children}
      {!!childrenCheckedCount && (
        <sup class={{ [`${prefix}__count`]: true }} slot="after">
          {childrenCheckedCount}
        </sup>
      )}
      {expandable && (
        <KsIconChevronRight
          class={{
            [`${prefix}__chevron--icon`]: true,
          }}
          slot="after"
          size={14}
        />
      )}
    </KsMenuItemBase>
  );
};
