import { Value } from '@src/components/ks-menu-item/types';
import { SingleValueType, CascaderDataNode, CascaderSearchNode } from '../types';
import { DataEntity } from '@src/components/ks-tree-view/utils';
import { VALUE_SPLIT } from '../constants';

export const toPathKey = (valuePath: Readonly<SingleValueType>) => valuePath.join(VALUE_SPLIT);

export const toPathKeys = (valuePaths: SingleValueType[]) => valuePaths.map(toPathKey);

function isMultipleValue(value: SingleValueType | SingleValueType[]): value is SingleValueType[] {
  return Array.isArray(value) && Array.isArray(value[0]);
}

export function toRawValues(value?: SingleValueType | SingleValueType[]): SingleValueType[] {
  if (!value) {
    return [];
  }

  if (isMultipleValue(value)) {
    return value;
  }

  return (value.length === 0 ? [] : [value]).map((val) => (Array.isArray(val) ? val : [val]));
}

export function getValueByKeyPath(
  keys: Value[],
  keyPathEntities: Record<string, DataEntity<CascaderDataNode>>,
): SingleValueType[] {
  return keys.map((key) => {
    const { nodes } = keyPathEntities[key]!;
    return nodes.map((node) => node.value);
  });
}

export function noop() {
  // DO NOTHING
}

export function isLeaf(option: CascaderDataNode | CascaderSearchNode) {
  return (option as CascaderDataNode).isLeaf ?? !option.children?.length;
}
